def code(rel,ranges,title,url,marks=()):
    lines=(R/rel).read_text(encoding='utf-8-sig').splitlines()
    rows=[]
    for k,(a,b) in enumerate(ranges):
        if k: rows.append('<div class="omitted">… 중간 코드 생략 …</div>')
        selected=lines[a-1:b]
        trim=min((len(x)-len(x.lstrip()) for x in selected if x.strip()),default=0)
        for n,line in enumerate(selected,a):
            text=html.escape(line[trim:].replace('\t','  '))
            text=re.sub(r'\b(return|if|while|float|int|bool|const|true|false|void)\b',r'<b>\1</b>',text)
            rows.append(f'<div class="line {"mark" if n in marks else ""}"><span class="ln">{n}</span><code>{text or " "}</code></div>')
    return '<div class="codebox"><div class="codehead"><strong>'+title+'</strong>'+link(url,'원본')+'</div><div class="filename">'+html.escape(Path(rel).name)+' · 실제 소스 발췌 / 행 번호 유지</div><div class="codebody">'+''.join(rows)+'</div></div>'

def step(n,title,description,block,example=''):
    return f'<article class="step"><div class="annotation"><span class="stepnum">{n}</span><h3>{title}</h3><p>{description}</p>{f"<div class=example>{example}</div>" if example else ""}</div>{block}</article>'

def header(id,num,title,desc,scope,img):
    return f'<section id="{id}" class="case"><div class="casehead"><div><span class="label">CASE {num}</span><h2>{title}</h2><p>{desc}</p><div class="scope">{scope}</div></div><img src="{img}" alt="{title} 구현 화면"></div>'

